// Independent Go verifier for licenses generated by tools/license.mjs.
package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"time"
	"la-erp/backend/license"
)

func main() {
	file := flag.String("file", "", "license JSON file")
	public := flag.String("public", "", "Base64 public key file")
	machine := flag.String("machine", "", "expected machine ID; default: local Linux identity")
	edition := flag.String("edition", "pro", "expected edition")
	flag.Parse()
	if *file == "" || *public == "" { fmt.Fprintln(os.Stderr, "-file and -public are required"); os.Exit(2) }
	data, err := os.ReadFile(*file)
	if err != nil { fail(err) }
	var record license.File
	if err := json.Unmarshal(data, &record); err != nil { fail(err) }
	key, err := os.ReadFile(*public)
	if err != nil { fail(err) }
	if *machine == "" { *machine, err = license.MachineID("/"); if err != nil { fail(err) } }
	if err := license.Verify(record, string(key), *machine, *edition, time.Now()); err != nil { fail(err) }
	fmt.Println("valid")
}

func fail(err error) { fmt.Fprintln(os.Stderr, err); os.Exit(1) }
